const tabId = 845789484;
const details = await browserjs(tabId, () => {
  // Let's find all hospital ranking rows or cards
  // Let's inspect elements with hospital info
  const items = [];
  const articles = document.querySelectorAll("article, [class*='DetailCard'], [class*='RankList']");

  // Or let's just inspect text around the hospital names
  const links = Array.from(document.querySelectorAll("a[href*='/best-hospitals/area/tx/']"));
  const seen = new Set();
  for (const a of links) {
    const href = a.href;
    if (seen.has(href) || !a.textContent.trim()) continue;
    seen.add(href);

    // traverse up to find card container
    let card = a.closest("[class*='Card']") || a.parentElement;
    while (card && card.tagName !== 'BODY' && !card.innerText.includes("Ranked") && !card.innerText.includes("High Performing") && !card.innerText.includes("#")) {
      card = card.parentElement;
    }
    items.push({
      name: a.textContent.trim(),
      url: href,
      cardText: (card ? card.innerText : a.parentElement?.innerText)?.replace(/\n+/g, " -- ")?.slice(0, 500)
    });
  }
  return items;
});
console.log(JSON.stringify(details, null, 2));

