async function searchDDG(query) {
  await tool.navigate({ tabId, url: `https://duckduckgo.com/?q=${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });
  return await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll("article h2 a, [data-testid='result-title-a']")).map(a => ({
      title: a.textContent?.trim(),
      href: a.href
    })).slice(0, 5);
  });
}

// 1. Houston Methodist cardiovascular surgery
