console.log("1. Houston Methodist:", JSON.stringify(hm, null, 2));

// 2. UT Southwestern heart surgery
const utsw = await searchDDG("UT Southwestern Medical Center heart surgery CABG valve");
console.log("2. UT Southwestern:", JSON.stringify(utsw, null, 2));

