const createRes = await tool.tabs_create({ url: "https://www.bswhealth.com/the-heart-hospital/cardiac-surgery" });
const tabId3 = createRes.details.tabId;
console.log("Created tab for BSW Plano:", tabId3);

// Wait a bit for navigation
let ready = false;
for (let i = 0; i < 10; i++) {
  const tabs = await tool.tabs_context({});
  const t = tabs.pages.find(p => p.tabId === tabId3);
  if (t && t.url && !t.url.startsWith("chrome://") && t.url !== "about:blank") {
    ready = true;
    break;
  }
  await new Promise(r => setTimeout(r, 500));
}

await tool.wait_for({ tabId: tabId3, condition: "dom_settled", timeout_ms: 6000 });

const pageInfo3 = await browserjs(tabId3, () => {
  const text = document.body.innerText;
  return {
    url: window.location.href,
    title: document.title,
    hasCABG: /bypass|CABG/i.test(text),
    hasValve: /valve/i.test(text),
    hasAortic: /aortic/i.test(text),
    snippets: [
      text.match(/.{0,50}(?:bypass|CABG).{0,50}/i)?.[0],
      text.match(/.{0,50}(?:valve).{0,50}/i)?.[0],
      text.match(/.{0,50}(?:aortic).{0,50}/i)?.[0]
    ]
  };
});
console.log("Tab 3 (BSW Plano) Info:", JSON.stringify(pageInfo3, null, 2));

