// Let's see what is inside the iframe
const iframeInfo = await browserjs(cryptTabId, () => {
  const outer = document.getElementById("sbox-iframe");
  if (!outer) return "No outer iframe";
  try {
    const doc = outer.contentDocument || outer.contentWindow.document;
    const innerIframes = Array.from(doc.querySelectorAll("iframe")).map(f => ({
      id: f.id,
      src: f.src,
      w: f.offsetWidth,
      h: f.offsetHeight
    }));
    return {
      innerIframes,
      docReady: doc.readyState,
      bodyText: doc.body.innerText.slice(0, 500)
    };
  } catch (e) {
    return "CORS restricted: " + e.message;
  }
});
console.log("Iframe info:", JSON.stringify(iframeInfo, null, 2));

